const html = $input.first().json.data;
const match = html.match(/window\.__SERVER_APP_STATE__\s*=\s*(.+?)(?=<\/script>)/s);
if (!match) throw new Error('Could not find __SERVER_APP_STATE__ in homepage HTML');
let raw = match[1].trim().replace(/;\s*$/, '').replace(/\bundefined\b/g, 'null');
let data;
try { data = JSON.parse(raw); } catch(e) { throw new Error('Parse failed: ' + e.message); }
const guides = data?.initialData?.helpcenterData?.guides || [];
if (guides.length === 0) throw new Error('No guides found');
return guides.map(g => {
  const gid = g.guideId;
  const title = g?.titles?.en?.title || 'Untitled';
  const firstStepId = g.firstStepId;
  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  const url = `https://biktrix.stonly.com/kb/guide/en/${slug}-${gid}/Steps/${firstStepId}`;
  return { json: { guideId: gid, title, firstStepId, url } };
});

const items = $input.all();
const guides = $('Extract Guide List').all();
const out = [];
const cleanHtml = (s) => (s || '')
  .replace(/<script[\s\S]*?<\/script>/gi,'')
  .replace(/<style[\s\S]*?<\/style>/gi,'')
  .replace(/<br\s*\/?>/gi,'\n')
  .replace(/<\/p>/gi,'\n')
  .replace(/<\/li>/gi,'\n')
  .replace(/<[^>]+>/g,' ')
  .replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>')
  .replace(/&quot;/g,'"').replace(/&#39;/g,"'")
  .replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();
for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data;
  const guide = guides[i] ? guides[i].json : {};
  if (!html) continue;
  const m = html.match(/window\.__SERVER_APP_STATE__\s*=\s*(.+?)(?=<\/script>)/s);
  if (!m) continue;
  let raw = m[1].trim().replace(/;\s*$/,'').replace(/\bundefined\b/g,'null');
  let data;
  try { data = JSON.parse(raw); } catch(e){ continue; }
  const steps = data?.initialData?.loadedGuide?.steps || [];
  for (const step of steps) {
    for (const mod of (step.stepModule || [])) {
      if (mod.type !== 'CONTENT') continue;
      const c = mod?.content?.en || {};
      const st = c.title || '';
      const body = cleanHtml(c.content || '');
      if (!st && !body) continue;
      const text = (st && body) ? `${st}\n\n${body}` : (st || body);
      if (text.length < 15) continue;
      out.push({ json: { text, url: guide.url, guideTitle: guide.title, guideId: String(guide.guideId), stepId: String(step.stepId), stepTitle: st }, pairedItem: { item: i } });
    }
  }
}
return out;

const emb = $json.data[0].embedding;
const c = $('Extract and Chunk Steps').item.json;
function hashUUID(str){
  let h1=0x811c9dc5,h2=0x811c9dc5;
  for(let i=0;i<str.length;i++){const ch=str.charCodeAt(i); h1=Math.imul(h1^ch,16777619)>>>0; h2=Math.imul(h2^(ch+13),16777619)>>>0;}
  const hex=(h1.toString(16).padStart(8,'0')+h2.toString(16).padStart(8,'0')).padEnd(32,'0').slice(0,32);
  return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20,32)}`;
}
const id = hashUUID(`${c.guideId}-${c.stepId}-${(c.text||'').length}`);
return { json: { body: { points: [ { id, vector: emb, payload: { text:c.text, url:c.url, guideTitle:c.guideTitle, guideId:c.guideId, stepId:c.stepId, stepTitle:c.stepTitle } } ] } } };
